// The APCCMMA emblem the printed license certificate carries at its head: web/img/logo.png (256×256, made from build/Logo.png), byte for byte,
// as a data URI. The certificate prints from a hidden window with JavaScript off and nothing loaded from outside, and build/Logo.png is not
// packaged, so the picture travels inside the page. shared/license-certificate.test.js checks it still matches web/img/logo.png.
// To refresh it after the logo changes, re-encode web/img/logo.png as base64 into the string below.
export const CERTIFICATE_EMBLEM = 'data:image/png;base64,';
